  // Activate license
  async function activateLicense(result) {
    const targetDocument = window.top ? window.top.document : document;
    const prompt = targetDocument.getElementById('squarehero-install-prompt');
    if (!prompt) return;

    const wrapper = prompt.querySelector('.install-wrapper');

    // Show activating message
    wrapper.innerHTML = `
      <div class="logo-container">
        <div class="logo-wrapper">
          <img src="${logoURL}" alt="SquareHero Logo" style="width: 100%; height: 100%; object-fit: contain;">
        </div>
      </div>
      
      <div class="progress-content">
        <p class="progress-title">Activating License...</p>
      </div>
    `;

    console.log('Activating site license...');

    try {
      const activationResponse = await fetch('https://activatesitefrominstallation-n6bvhzbxla-uc.a.run.app', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ websiteId: result.websiteId })
      });

      const activationResult = await activationResponse.json();

      if (activationResult.success) {
        console.log('✅ Site license activated successfully');
        showActivatedScreen(result);
      } else if (activationResult.limitReached) {
        console.warn('⚠️ Site limit reached:', activationResult.error);
        showLimitReachedScreen(activationResult, result.websiteId);
      } else if (activationResult.needsSubscription) {
        console.warn('⚠️ Subscription required:', activationResult.error);
        showSubscriptionRequiredScreen(result.websiteId);
      } else {
        console.warn('⚠️ Site activation failed:', activationResult.error);
        showActivationError(activationResult.error);
      }
    } catch (activationError) {
      console.error('Error activating site license:', activationError);
      showActivationError('Failed to activate license. Please try again later.');
    }
  }

