  // Fetch site title from Squarespace JSON endpoint
  async function fetchSquarespaceSiteTitle() {
    try {
      const baseUrl = window.location.origin;
      const jsonUrl = `${baseUrl}/?format=json-pretty`;

      const response = await fetch(jsonUrl);
      if (response.ok) {
        const data = await response.json();
        const siteTitle = data?.website?.siteTitle;
        if (siteTitle) {
          return siteTitle;
        }
      }
    } catch (error) {
      console.log('SquareHero: Error fetching site title:', error);
    }
    return null;
  }

  // Remove sh-helper from header injection
  // Disconnect SquareHero extension from Squarespace
  async function disconnectSquareHeroExtension() {
    try {
      // Get the crumb token for CSRF protection
      const crumb = document.cookie.split(';')
        .find(c => c.trim().startsWith('crumb='))
        ?.split('=')[1];

      if (!crumb) {
        throw new Error('No crumb token found');
      }

      console.log('🔍 Fetching extension details to find SquareHero connection...');

      // First, get the list of extensions to find SquareHero's connection ID
      const detailsResponse = await fetch(`${window.location.origin}/api/1/extensions/details?preferredLocale=en-US`, {
        method: 'GET',
        headers: {
          'accept': 'application/json, text/plain, */*',
          'x-csrf-token': crumb
        },
        credentials: 'include'
      });

      if (!detailsResponse.ok) {
        throw new Error(`Failed to fetch extensions: ${detailsResponse.status}`);
      }

      const detailsData = await detailsResponse.json();
      console.log('📦 Extensions data retrieved:', detailsData);

      // Find SquareHero extension by clientId
      const squareHeroClientId = 'eCKbTYOjcWFJcuWwYtOask1ILkJpO6mv';
      const squareHeroExtension = detailsData.extensions?.find(ext =>
        ext.clientId === squareHeroClientId && ext.connected
      );

      if (!squareHeroExtension) {
        console.log('ℹ️ SquareHero extension not found or not connected');
        return { success: true, message: 'Extension not connected' };
      }

      const connectionId = squareHeroExtension.connectionDetails?.id;
      if (!connectionId) {
        throw new Error('No connection ID found for SquareHero extension');
      }

      console.log('🔗 Found SquareHero connection ID:', connectionId);

      // Now disconnect the extension using the connection ID
      const disconnectResponse = await fetch(`${window.location.origin}/api/1/extensions/connections/${connectionId}`, {
        method: 'DELETE',
        headers: {
          'accept': 'application/json, text/plain, */*',
          'x-csrf-token': crumb
        },
        credentials: 'include'
      });

      if (!disconnectResponse.ok) {
        throw new Error(`Failed to disconnect extension: ${disconnectResponse.status}`);
      }

      console.log('🔓 SquareHero extension disconnected successfully');
      return { success: true, message: 'Extension disconnected successfully' };

    } catch (error) {
      console.error('❌ Error disconnecting SquareHero extension:', error);
      throw error;
    }
  }

  async function removeHeaderInjection() {
    try {
      const crumb = document.cookie.split(';')
        .find(c => c.trim().startsWith('crumb='))
        ?.split('=')[1];

      if (!crumb) {
        throw new Error('Authentication token not found');
      }

      // Get current injection settings
      const getResponse = await fetch(`${window.location.origin}/api/config/GetInjectionSettings`, {
        method: "GET",
        headers: {
          "accept": "application/json",
          "x-csrf-token": crumb
        },
        credentials: "include"
      });

      if (!getResponse.ok) {
        throw new Error(`Failed to get injection settings: ${getResponse.status}`);
      }

      const settings = await getResponse.json();
      let headerCode = settings.header || '';

      // Find and remove the sh-helper code block
      const markerStart = `<!-- ${SH_HELPER_MARKER}_START -->`;
      const markerEnd = `<!-- ${SH_HELPER_MARKER}_END -->`;

      const startIndex = headerCode.indexOf(markerStart);
      const endIndex = headerCode.indexOf(markerEnd);

      if (startIndex !== -1 && endIndex !== -1) {
        headerCode = headerCode.substring(0, startIndex) +
          headerCode.substring(endIndex + markerEnd.length);
      }

      // Save updated settings
      const formBody = new URLSearchParams();
      formBody.append('header', headerCode);
      formBody.append('footer', settings.footer || '');

      const saveResponse = await fetch(`${window.location.origin}/api/config/SaveInjectionSettings`, {
        method: "POST",
        headers: {
          "content-type": "application/x-www-form-urlencoded",
          "x-csrf-token": crumb
        },
        body: formBody.toString(),
        credentials: "include"
      });

      if (!saveResponse.ok) {
        throw new Error(`Failed to remove header injection: ${saveResponse.status}`);
      }

      return { success: true };
    } catch (error) {
      console.error("Error removing header injection:", error);
      throw error;
    }
  }

  // Uninstall plugin completely
  async function uninstallPlugin(updateProgress) {
    try {
      updateProgress(10, "Getting page information...");

      const crumb = document.cookie.split(';')
        .find(c => c.trim().startsWith('crumb='))
        ?.split('=')[1];

      if (!crumb) {
        throw new Error("Could not find authentication token");
      }

      // Get site layout to find the plugin page ID
      const layoutResponse = await fetch(`${window.location.origin}/api/commondata/GetSiteLayout`, {
        method: "GET",
        headers: {
          "accept": "application/json",
          "x-csrf-token": crumb
        },
        credentials: "include"
      });

      if (!layoutResponse.ok) {
        throw new Error(`Failed to get site layout: ${layoutResponse.status}`);
      }

      const layout = await layoutResponse.json();
      let pluginPageId = null;

      // Search for the plugin page using the same logic as checkIfPageExists
      function findPageId(siteLayout, targetUrlId) {
        // Check navigation sections
        if (siteLayout.layout && Array.isArray(siteLayout.layout)) {
          for (const nav of siteLayout.layout) {
            if (nav && nav.links && Array.isArray(nav.links)) {
              for (const linkObj of nav.links) {
                if (linkObj && linkObj.urlId === targetUrlId) {
                  return linkObj.collectionId || linkObj.id;
                }
              }
            }
          }
        }

        // Check collections directly
        if (siteLayout.collections && Array.isArray(siteLayout.collections)) {
          for (const collection of siteLayout.collections) {
            if (collection && collection.urlId === targetUrlId) {
              return collection.id;
            }
          }
        }

        return null;
      }

      pluginPageId = findPageId(layout, 'sh-product-manager-7qk3z8pl');

      if (!pluginPageId) {
        throw new Error("Plugin page not found");
      }

      updateProgress(30, "Removing SquareHero core files...");

      // Remove header injection
      await removeHeaderInjection();

      updateProgress(70, "Removing plugin page...");

      // Delete the page
      const deleteResponse = await fetch(`${window.location.origin}/api/commondata/RemoveCollection`, {
        method: "POST",
        headers: {
          "content-type": "application/x-www-form-urlencoded",
          "x-csrf-token": crumb,
          "accept": "application/json, text/plain, */*"
        },
        body: `collectionId=${pluginPageId}`,
        credentials: "include"
      });

      if (!deleteResponse.ok) {
        throw new Error(`Failed to delete page: ${deleteResponse.status}`);
      }

      updateProgress(90, "Deactivating license...");

      // Deactivate license in Firebase
      try {
        const websiteId = await getSquarespaceWebsiteId();
        const deactivationResponse = await fetch('https://activatesitefrominstallation-n6bvhzbxla-uc.a.run.app', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            websiteId: websiteId,
            deactivate: true
          })
        });

        const deactivationResult = await deactivationResponse.json();
        if (deactivationResult.success) {
          console.log('✅ License deactivated successfully');
        } else {
          console.warn('⚠️ License deactivation failed:', deactivationResult.error);
        }
      } catch (deactivationError) {
        console.error('Error deactivating license:', deactivationError);
        // Continue with uninstall even if deactivation fails
      }

      updateProgress(100, "Uninstall complete!");

      // Delete installation cookie
      deleteCookie('sh_plugin_installed');
      console.log('SquareHero: Installation cookie deleted');

      return { success: true };
    } catch (error) {
      console.error("Uninstall error:", error);
      return { success: false, error: error.message };
    }
  }

